#include "scenario/scenario.hpp"
#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <iomanip>
int main(int argc,char**argv){if(argc<2||std::string(argv[1])=="--help"||std::string(argv[1])=="-h"){std::cout<<"scenario-calculator <run|compare|cohort|seek|breakeven|sensitivity|check> <scenario.ini> [--format text|csv|markdown|json]\nAll results are HYPOTHETICAL / NOT A FORECAST.\n";return argc<2?1:0;}std::string cmd=argv[1],format="text";if(cmd!="run"&&cmd!="compare"&&cmd!="cohort"&&cmd!="seek"&&cmd!="breakeven"&&cmd!="sensitivity"&&cmd!="check"){std::cerr<<"Unknown command: "<<cmd<<"\n";return 2;}if(argc<3){std::cerr<<"A scenario file is required\n";return 2;}std::vector<std::string> files;for(int i=2;i<argc;++i){std::string a=argv[i];if(a=="--format"&&i+1<argc)format=argv[++i];else if(a.rfind("--",0)==0){std::cerr<<"Unknown flag: "<<a<<"\n";return 2;}else files.push_back(a);}try{if(cmd=="compare"){if(files.size()<2){std::cerr<<"compare requires at least two scenario files\n";return 2;}std::cout<<"HYPOTHETICAL / NOT A FORECAST — scenario comparison\n";for(const auto&f:files){auto m=scenario::load(f);auto issues=scenario::validate(m);if(!issues.empty()){std::cerr<<f<<": invalid scenario\n";return 1;}double normalized=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);std::cout<<std::left<<std::setw(30)<<m.name<<" currency="<<m.currency<<" monthly_price="<<(m.has_price?m.currency+" "+std::to_string(normalized):"unavailable")<<" target_payers="<<(m.has_price?std::to_string(static_cast<long long>(std::ceil(m.target/normalized))):"unavailable")<<" replacements="<<(m.has_price&&m.has_loss?std::to_string(static_cast<long long>(std::ceil(m.target/normalized*m.loss))):"unavailable")<<"\n";}return 0;}if(files.size()!=1){std::cerr<<cmd<<" requires exactly one scenario file\n";return 2;}auto m=scenario::load(files.front());std::cout<<scenario::execute(m,cmd,format);}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
